export default pattern<VerbListFrameInput, VerbListFrameOutput>(({
  input,
  addItem: iframeStream0,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const output = new Writable<IframeOutputData>(DEFAULT_OUTPUT);
  const iframeInput = input ?? DEFAULT_INPUT;
  const context = IframeContext({
    input: iframeInput,
    state,
    output,
    ["addItem"]: iframeStream0,
  });

  return {
    [NAME]: "Verb list",
    [UI]: (
      <div style={{ width: "100%", height: "100vh" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
            ["addItem"]: "stream",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
